preConditionHook:
highestClose = close[0];
lowestClose = close[0];
// Mirrors EasyLanguage's Extremes(), which Highest()/Lowest() call: seeded
// at bar 0, scanning bars 1..Length-1, strict comparison (so a tie keeps the
// earliest bar). Extremes is EL SOURCE, and its `Price[Value1] > MyVal` is an
// ordinary EL relational operator -- so it carries the same tolerance every
// other EL comparison does, and these use el_gt/el_lt rather than > and <.
for (int i = 1; i < (int)lookback; ++i) {
    if (el_gt(close[i], highestClose)) highestClose = close[i];
    if (el_lt(close[i], lowestClose)) lowestClose = close[i];
}
